/**
 * Issue UUID. Not the public code — the public code is only for the shareable page.
 */
export type IssueIdPath = string;

export type MatchIdPath = string;

export type CommentIdPath = string;

/**
 * The unguessable token issued in the 201 body of a concealed report,
 * stored client-side. It authorises access to exactly the issues created
 * with it and nothing else.
 *
 * The server holds no plaintext copy of any token it issued, so a
 * presented token is verified by hashing it under the pepper and
 * comparing digests in constant time.
 *
 * A header rather than a query parameter so the value stays out of access
 * logs, proxy logs and `Referer` headers.
 *
 * Failure modes are deliberately asymmetric: a **missing** header is 401
 * UNAUTHENTICATED, but a **present but unrecognised** header is 404, the
 * same answer as an unknown issue id. A caller with a bad token learns
 * nothing about whether anything exists, and the client renders one
 * "this link is not valid" state instead of two.
 *
 */
export type TrackingTokenHeader = string;

export type UserIdPath = string;

/**
 * Zero-based.
 */
export type PageParam = number;

export type SizeParam = number;

/**
 * Client-generated UUID. Replaying the same key from the same reporter
 * returns the original 201 body rather than creating a second report.
 * This exists so a double-tap or a retry on a flaky connection cannot
 * produce duplicate reports — which would then pollute the duplicate
 * detection built in P2 and P3.
 *
 * "The same reporter" means the user id when signed in, and the salted IP
 * hash when concealed, so one concealed reporter retrying cannot collide
 * with an unrelated concealed reporter who happened to generate the same
 * UUID.
 *
 * A replay returns the original body *including* the original
 * `trackingToken`, which the server re-derives rather than retains. Reuse
 * of a key with a materially different payload is a client bug: the
 * original report is returned unchanged, the mismatch is logged, and no
 * second report is created — so the bug is visible rather than silently
 * dropping a citizen's report.
 *
 */
export type IdempotencyKey = string;

